  .play-note { display: none; }
  .menu-foot { padding-top: 7px; margin-top: 10px; }
  .hud-top { padding: 12px; }
  .hud-score { gap: 12px; min-width: 95px; }
  .hud-wave__name { display: none; }
  .crowd-meter { width: 132px; }
  .crowd-meter__labels span { font-size: 6px; }
  .crowd-cheer { font-size: 6px; top: 31px; }
  .enemy-track { top: 76px; }
  .kill-feed { top: 90px; right: 12px; }
  .hud-bottom { left: 12px; right: 12px; bottom: 143px; grid-template-columns: 1fr auto; gap: 12px; }
  .vitals { grid-column: 1; }
