@media (max-width: 680px) and (orientation: portrait) {
  .touch-actions { bottom: max(22px, env(safe-area-inset-bottom)); }
  .hud-bottom { bottom: 145px; }
}

@media (max-height: 560px) {
  .title { font-size: 62px; }
