@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
}

import * as THREE from 'three';

export const TAU = Math.PI * 2;

export const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rand = (min = 0, max = 1) => min + Math.random() * (max - min);
export const randInt = (min, max) => Math.floor(rand(min, max + 1));
export const pick = (list) => list[Math.floor(Math.random() * list.length)];
export const easeOutCubic = (t) => 1 - Math.pow(1 - clamp(t, 0, 1), 3);
export const easeInCubic = (t) => Math.pow(clamp(t, 0, 1), 3);
export const easeInOutQuad = (t) => {
  const x = clamp(t, 0, 1);
  return x < 0.5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
};

export function angleDelta(a, b) {
  let d = (b - a + Math.PI) % TAU;
  if (d < 0) d += TAU;
  return d - Math.PI;
}

export function roman(value) {
  const table = [
    [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'],
    [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
  ];
  let n = Math.max(0, Math.floor(value));
  let out = '';
  for (const [amount, numeral] of table) {
    while (n >= amount) {
      out += numeral;
      n -= amount;
    }
  }
  return out || '0';
}

export function canvas2d(width, height = width) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  return { canvas, ctx: canvas.getContext('2d') };
}

export function textureFromCanvas(canvas, { repeat = null, colorSpace = true } = {}) {
  const texture = new THREE.CanvasTexture(canvas);
  if (colorSpace) texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  if (repeat) {
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(repeat[0], repeat[1]);
  }
  return texture;
}

export function makeNoiseTexture(size, base, options = {}) {
  const { canvas, ctx } = canvas2d(size);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, size, size);

  const {
    specks = 2800,
    speckColors = ['#000000', '#ffffff'],
    speckAlpha = 0.08,
    speckSize = 1.6,
    streaks = 0,
    streakColor = '#000000',
  } = options;

  for (let i = 0; i < specks; i++) {
    ctx.globalAlpha = rand(speckAlpha * 0.15, speckAlpha);
    ctx.fillStyle = pick(speckColors);
    const s = rand(0.4, speckSize);
    ctx.fillRect(rand(0, size), rand(0, size), s, s);
  }

  for (let i = 0; i < streaks; i++) {
    ctx.globalAlpha = rand(0.02, 0.1);
    ctx.strokeStyle = streakColor;
    ctx.lineWidth = rand(0.5, 4);
    ctx.beginPath();
    let x = rand(0, size);
    let y = rand(0, size);
    ctx.moveTo(x, y);
    for (let j = 0; j < 5; j++) {
      x += rand(-18, 18);
      y += rand(4, 26);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  ctx.globalAlpha = 1;
  return textureFromCanvas(canvas);
}

export function radialTexture(size = 64, inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  const { canvas, ctx } = canvas2d(size);
  const gradient = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  gradient.addColorStop(0, inner);
  gradient.addColorStop(0.38, inner);
  gradient.addColorStop(1, outer);
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);
  return textureFromCanvas(canvas);
}

export function disposeObject(root) {
  if (!root) return;
  root.traverse((child) => {
    if (child.isMesh || child.isPoints || child.isLine) {
      child.geometry?.dispose?.();
      const materials = Array.isArray(child.material) ? child.material : [child.material];
      for (const material of materials) {
        if (!material) continue;
        for (const key of Object.keys(material)) {
          const value = material[key];
          if (value?.isTexture) value.dispose?.();
        }
        material.dispose?.();
      }
    }
  });
}

export function projectedScreenDistance(camera, point, target = new THREE.Vector2()) {
  const projected = point.clone().project(camera);
  return target.set(projected.x, projected.y).length();
}

export function makeBoneMaterial() {
  return new THREE.MeshStandardMaterial({
    color: 0xe4d7bd,
    roughness: 0.68,
    metalness: 0.02,
    flatShading: true,
  });
}

export function seededRandom(seed) {
  let value = seed % 2147483647;
  if (value <= 0) value += 2147483646;
  return () => {
    value = (value * 16807) % 2147483647;
    return (value - 1) / 2147483646;
  };
}

import { rand } from './utils.js';

export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.muted = false;
    this.ambientStarted = false;
    this.lastStep = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.62;
    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 18;
    compressor.ratio.value = 7;
    compressor.attack.value = 0.003;
    compressor.release.value = 0.24;
    this.master.connect(compressor);
    compressor.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoiseBuffer(3);
  }

  makeNoiseBuffer(seconds) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.18 + white * 0.82;
      data[i] = last;
    }
    return buffer;
  }

  get now() {
    return this.ctx?.currentTime ?? 0;
  }

  noiseSource() {
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    source.loop = true;
    source.loopEnd = this.noiseBuffer.duration;
    return source;
  }

  toggleMute() {
    if (!this.master) return false;
    this.muted = !this.muted;
    this.master.gain.cancelScheduledValues(this.now);
    this.master.gain.linearRampToValueAtTime(this.muted ? 0 : 0.62, this.now + 0.08);
    return this.muted;
  }

  startAmbient() {
    if (!this.ctx || this.ambientStarted) return;
    this.ambientStarted = true;
    const t = this.now;

    // A low sea of crowd matter.
    const crowd = this.noiseSource();
    const crowdFilter = this.ctx.createBiquadFilter();
    crowdFilter.type = 'bandpass';
    crowdFilter.frequency.value = 420;
    crowdFilter.Q.value = 0.65;
    const crowdGain = this.ctx.createGain();
    crowdGain.gain.setValueAtTime(0.0001, t);
    crowdGain.gain.exponentialRampToValueAtTime(0.024, t + 1.5);
    crowd.connect(crowdFilter);
    crowdFilter.connect(crowdGain);
    crowdGain.connect(this.master);
    crowd.start(t);

    const lfo = this.ctx.createOscillator();
    const lfoGain = this.ctx.createGain();
    lfo.frequency.value = 0.17;
    lfoGain.gain.value = 0.007;
    lfo.connect(lfoGain);
    lfoGain.connect(crowdGain.gain);
    lfo.start(t);

    // Desert wind over the top.
    const wind = this.noiseSource();
    wind.playbackRate.value = 0.55;
    const windFilter = this.ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 230;
    const windGain = this.ctx.createGain();
    windGain.gain.setValueAtTime(0.0001, t);
    windGain.gain.exponentialRampToValueAtTime(0.017, t + 2.1);
    wind.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(this.master);
    wind.start(t);
  }

  tone({ frequency = 220, endFrequency = null, type = 'sine', gain = 0.1, duration = 0.3, attack = 0.004, delay = 0, detune = 0 }) {
    if (!this.ctx) return;
    const t = this.now + delay;
    const osc = this.ctx.createOscillator();
    const amp = this.ctx.createGain();
    osc.type = type;
    osc.detune.value = detune;
    osc.frequency.setValueAtTime(frequency, t);
    if (endFrequency !== null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFrequency), t + duration);
    amp.gain.setValueAtTime(0.0001, t);
    amp.gain.linearRampToValueAtTime(gain, t + attack);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(amp);
    amp.connect(this.master);
    osc.start(t);
    osc.stop(t + duration + 0.02);
  }

  noise({
    gain = 0.1,
    duration = 0.25,
    type = 'bandpass',
    frequency = 900,
    endFrequency = null,
    Q = 1,
    attack = 0.003,
    delay = 0,
    playbackRate = 1,
  }) {
    if (!this.ctx) return;
    const t = this.now + delay;
    const source = this.noiseSource();
    source.playbackRate.value = playbackRate;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.Q.value = Q;
    filter.frequency.setValueAtTime(frequency, t);
    if (endFrequency !== null) filter.frequency.exponentialRampToValueAtTime(Math.max(30, endFrequency), t + duration);
    const amp = this.ctx.createGain();
    amp.gain.setValueAtTime(0.0001, t);
    amp.gain.linearRampToValueAtTime(gain, t + attack);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    source.connect(filter);
    filter.connect(amp);
    amp.connect(this.master);
    source.start(t);
    source.stop(t + duration + 0.02);
  }

  swing(weapon = 'sword') {
    if (!this.ctx) return;
    const heavy = weapon === 'hammer';
    this.noise({
      type: 'bandpass',
      frequency: heavy ? 260 : 880,
      endFrequency: heavy ? 110 : 2400,
      Q: heavy ? 1.4 : 2.2,
      gain: heavy ? 0.13 : 0.09,
      duration: heavy ? 0.34 : 0.2,
      playbackRate: heavy ? 0.8 : 1.2,
    });
    this.noise({
      type: 'highpass',
      frequency: 3100,
      gain: 0.018,
      duration: 0.12,
      playbackRate: 1.7,
    });
  }

  flesh(power = 1) {
    if (!this.ctx) return;
    this.tone({ frequency: 92, endFrequency: 44, type: 'sine', gain: 0.24 * power, duration: 0.2, attack: 0.002 });
    this.noise({ type: 'lowpass', frequency: 680, endFrequency: 180, gain: 0.17 * power, duration: 0.18, playbackRate: 0.8 });
    this.noise({ type: 'bandpass', frequency: 1900, endFrequency: 900, Q: 0.8, gain: 0.05 * power, duration: 0.09 });
  }

  boneBreak() {
    if (!this.ctx) return;
    this.noise({ type: 'highpass', frequency: 2600, gain: 0.14, duration: 0.1, playbackRate: 1.4 });
    this.noise({ type: 'bandpass', frequency: 780, endFrequency: 260, Q: 1.8, gain: 0.12, duration: 0.22 });
    this.tone({ frequency: 160, endFrequency: 76, type: 'triangle', gain: 0.13, duration: 0.25 });
  }

  metal() {
    if (!this.ctx) return;
    this.tone({ frequency: 1320, endFrequency: 940, type: 'triangle', gain: 0.07, duration: 0.24 });
    this.tone({ frequency: 1830, endFrequency: 1510, type: 'sine', gain: 0.035, duration: 0.2, detune: 9 });
    this.noise({ type: 'bandpass', frequency: 3200, Q: 2.4, gain: 0.05, duration: 0.16 });
  }

  hammer(power = 1) {
    if (!this.ctx) return;
    this.tone({ frequency: 64, endFrequency: 32, type: 'sine', gain: 0.35 * power, duration: 0.45, attack: 0.002 });
    this.noise({ type: 'lowpass', frequency: 440, endFrequency: 90, gain: 0.22 * power, duration: 0.4, playbackRate: 0.65 });
    this.metal();
  }

  scream(pitch = 1) {
    if (!this.ctx) return;
    const t = this.now;
    const osc = this.ctx.createOscillator();
    const vibrato = this.ctx.createOscillator();
    const vibratoGain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();
    const amp = this.ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(rand(220, 300) * pitch, t);
    osc.frequency.exponentialRampToValueAtTime(rand(90, 140) * pitch, t + 0.58);
    vibrato.frequency.value = 18;
    vibratoGain.gain.value = 9;
    filter.type = 'bandpass';
    filter.frequency.value = 780;
    filter.Q.value = 1.2;
    amp.gain.setValueAtTime(0.0001, t);
    amp.gain.linearRampToValueAtTime(0.035, t + 0.03);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + 0.68);
    vibrato.connect(vibratoGain);
    vibratoGain.connect(osc.frequency);
    osc.connect(filter);
    filter.connect(amp);
    amp.connect(this.master);
    osc.start(t);
    vibrato.start(t);
    osc.stop(t + 0.7);
    vibrato.stop(t + 0.7);
  }

  crowdCheer(intensity = 1) {
    if (!this.ctx) return;
    const t = this.now;
    const source = this.noiseSource();
    source.playbackRate.value = 0.9;
    const band = this.ctx.createBiquadFilter();
    band.type = 'bandpass';
    band.frequency.setValueAtTime(340, t);
    band.frequency.linearRampToValueAtTime(780, t + 0.55);
    band.frequency.linearRampToValueAtTime(410, t + 2.8);
    band.Q.value = 0.55;
    const amp = this.ctx.createGain();
    const peak = 0.1 * intensity;
    amp.gain.setValueAtTime(0.0001, t);
    amp.gain.linearRampToValueAtTime(peak, t + 0.12);
    amp.gain.exponentialRampToValueAtTime(0.0001, t + 2.9);
    source.connect(band);
    band.connect(amp);
    amp.connect(this.master);
    source.start(t);
    source.stop(t + 3);

    for (let i = 0; i < 15; i++) {
      this.noise({
        type: 'highpass',
        frequency: rand(900, 2100),
        Q: 0.7,
        gain: rand(0.015, 0.05) * intensity,
        duration: rand(0.035, 0.08),
        delay: rand(0.08, 1.9),
        attack: 0.001,
      });
    }

    this.tone({ frequency: 85, endFrequency: 62, type: 'sine', gain: 0.04 * intensity, duration: 1.2 });
  }

  gate() {
    if (!this.ctx) return;
    this.tone({ frequency: 48, endFrequency: 33, type: 'sawtooth', gain: 0.07, duration: 1.15 });
    this.noise({ type: 'lowpass', frequency: 360, endFrequency: 110, gain: 0.055, duration: 1.3, playbackRate: 0.55 });
    this.metal();
  }

  gong() {
    if (!this.ctx) return;
    this.tone({ frequency: 118, endFrequency: 72, type: 'sine', gain: 0.2, duration: 2.2, attack: 0.006 });
    this.tone({ frequency: 177, endFrequency: 110, type: 'sine', gain: 0.07, duration: 1.8, detune: -8 });
    this.tone({ frequency: 312, endFrequency: 260, type: 'triangle', gain: 0.03, duration: 1.3 });
  }

  footstep(sprint = false) {
    if (!this.ctx) return;
    const now = this.now;
    if (now - this.lastStep < (sprint ? 0.26 : 0.36)) return;
    this.lastStep = now;
    this.noise({ type: 'lowpass', frequency: rand(170, 260), gain: sprint ? 0.055 : 0.032, duration: 0.09, playbackRate: 0.55 });
    this.tone({ frequency: rand(62, 82), endFrequency: 45, type: 'sine', gain: sprint ? 0.05 : 0.025, duration: 0.1 });
  }

  ui() {
    if (!this.ctx) return;
    this.tone({ frequency: 640, endFrequency: 740, type: 'sine', gain: 0.025, duration: 0.06 });
  }

  deathCall() {
    if (!this.ctx) return;
    this.gong();
    this.tone({ frequency: 55, endFrequency: 28, type: 'sine', gain: 0.2, duration: 2.6 });
  }
}

import * as THREE from 'three';
import {
  canvas2d,
  textureFromCanvas,
  makeNoiseTexture,
  radialTexture,
  rand,
  randInt,
  pick,
  TAU,
  clamp,
} from './utils.js';

const BLOCK_LINES = '#22150e';

function sandTexture() {
  const { canvas, ctx } = canvas2d(512);
  ctx.fillStyle = '#8d6b40';
  ctx.fillRect(0, 0, 512, 512);

  const gradient = ctx.createLinearGradient(0, 0, 512, 512);
  gradient.addColorStop(0, 'rgba(206, 167, 105, .18)');
  gradient.addColorStop(0.46, 'rgba(67, 40, 20, .16)');
  gradient.addColorStop(1, 'rgba(224, 182, 117, .1)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 512, 512);

  for (let i = 0; i < 9000; i++) {
    const tone = Math.random() > 0.52 ? 255 : 0;
    ctx.globalAlpha = rand(0.012, 0.055);
    ctx.fillStyle = tone ? '#f4dfb5' : '#331f11';
    const s = rand(0.3, 2.1);
    ctx.fillRect(rand(0, 512), rand(0, 512), s, s);
  }

  // Trodden tracks and hairline cracks.
  for (let i = 0; i < 18; i++) {
    ctx.globalAlpha = rand(0.025, 0.08);
    ctx.strokeStyle = i % 3 === 0 ? '#d4b67e' : '#3a2414';
    ctx.lineWidth = rand(0.5, 2.2);
    ctx.beginPath();
    let x = rand(0, 512);
    let y = rand(0, 512);
    ctx.moveTo(x, y);
    for (let j = 0; j < randInt(4, 10); j++) {
      x += rand(-24, 24);
      y += rand(3, 18);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  for (let i = 0; i < 22; i++) {
    ctx.globalAlpha = rand(0.01, 0.035);
    ctx.fillStyle = '#f6dfb4';
    ctx.beginPath();
    ctx.ellipse(rand(0, 512), rand(0, 512), rand(18, 75), rand(2, 10), rand(0, TAU), 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  return textureFromCanvas(canvas, { repeat: [4, 4] });
}

function stoneTexture() {
  const { canvas, ctx } = canvas2d(512);
  ctx.fillStyle = '#4a3827';
  ctx.fillRect(0, 0, 512, 512);
  const rowHeight = 64;
  for (let row = 0; row < 8; row++) {
    const offset = row % 2 === 0 ? 0 : 52;
    for (let col = -1; col < 6; col++) {
      const x = col * 104 + offset;
      const y = row * rowHeight;
      const tone = randInt(47, 75);
      ctx.fillStyle = `rgb(${tone + 7}, ${tone - 2}, ${Math.max(24, tone - 13)})`;
      ctx.fillRect(x + 2, y + 2, 100, rowHeight - 4);
      ctx.globalAlpha = 0.22;
      ctx.fillStyle = '#d2a973';
      ctx.fillRect(x + 4, y + 4, 96, 2);
      ctx.globalAlpha = 1;
    }
  }
  for (let i = 0; i < 3600; i++) {
    ctx.globalAlpha = rand(0.02, 0.11);
    ctx.fillStyle = Math.random() > 0.5 ? '#e3c08b' : '#160d08';
    ctx.fillRect(rand(0, 512), rand(0, 512), rand(0.4, 2.2), rand(0.4, 2.2));
  }
  // Moss and old damp patches.
  for (let i = 0; i < 12; i++) {
    ctx.globalAlpha = rand(0.025, 0.095);
    ctx.fillStyle = i % 3 === 0 ? '#59613a' : '#150c08';
    ctx.beginPath();
    ctx.ellipse(rand(0, 512), rand(0, 512), rand(9, 38), rand(4, 15), rand(0, TAU), 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  return textureFromCanvas(canvas, { repeat: [10, 1.8] });
}

function bannerTexture() {
  const { canvas, ctx } = canvas2d(256, 512);
  const grad = ctx.createLinearGradient(0, 0, 256, 512);
  grad.addColorStop(0, '#5a0d0e');
  grad.addColorStop(0.5, '#370909');
  grad.addColorStop(1, '#1e0505');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 256, 512);

  ctx.globalAlpha = 0.35;
  for (let i = 0; i < 120; i++) {
    ctx.fillStyle = Math.random() > 0.5 ? '#000000' : '#b4553b';
    ctx.fillRect(rand(0, 256), rand(0, 512), rand(1, 4), rand(1, 30));
  }
  ctx.globalAlpha = 0.85;
  ctx.strokeStyle = '#b79354';
  ctx.lineWidth = 3;
  ctx.strokeRect(19, 20, 218, 470);
  ctx.lineWidth = 1;
  ctx.strokeStyle = '#5f4725';
  ctx.strokeRect(27, 28, 202, 454);

  ctx.fillStyle = '#b48e4f';
  ctx.beginPath();
  ctx.arc(128, 170, 63, 0, TAU);
  ctx.lineWidth = 3;
  ctx.stroke();

  // Skull sigil.
  ctx.fillStyle = '#c3a76d';
  ctx.beginPath();
  ctx.ellipse(128, 156, 26, 30, 0, 0, TAU);
  ctx.fill();
  ctx.fillRect(108, 166, 40, 24);
  ctx.fillStyle = '#3c1b0f';
  ctx.beginPath();
  ctx.arc(117, 154, 6, 0, TAU);
  ctx.arc(139, 154, 6, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(128, 160);
  ctx.lineTo(122, 171);
  ctx.lineTo(134, 171);
  ctx.closePath();
  ctx.fill();
  for (let i = 0; i < 5; i++) ctx.fillRect(113 + i * 7, 181, 3, 8);

  ctx.fillStyle = '#d2b06b';
  ctx.font = 'bold 30px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.fillText('BLOODPIT', 128, 295);
  ctx.fillStyle = '#8e7143';
  ctx.font = '10px Courier New, monospace';
  ctx.fillText('THE SANDS REMEMBER', 128, 324);

  // Ragged bottom.
  ctx.globalCompositeOperation = 'destination-out';
  ctx.beginPath();
  ctx.moveTo(0, 490);
  for (let x = 0; x <= 256; x += 18) {
    ctx.lineTo(x, 470 + rand(-13, 25));
    ctx.lineTo(x + 9, 495 + rand(-15, 8));
  }
  ctx.lineTo(256, 512);
  ctx.lineTo(0, 512);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  return textureFromCanvas(canvas);
}

function emblemTexture() {
  const { canvas, ctx } = canvas2d(512);
  ctx.translate(256, 256);
  ctx.strokeStyle = 'rgba(44, 22, 10, .7)';
  ctx.fillStyle = 'rgba(47, 20, 9, .3)';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(0, 0, 192, 0, TAU);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(0, 0, 170, 0, TAU);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 0, 76, 0, TAU);
  ctx.stroke();

  for (let i = 0; i < 16; i++) {
    ctx.save();
    ctx.rotate((i / 16) * TAU);
    ctx.beginPath();
    ctx.moveTo(82, 0);
    ctx.lineTo(150, -12);
    ctx.lineTo(170, 0);
    ctx.lineTo(150, 12);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    ctx.restore();
  }

  ctx.font = 'bold 46px Georgia, serif';
  ctx.textAlign = 'center';
  ctx.fillStyle = 'rgba(43, 19, 9, .7)';
  ctx.fillText('BLOODPIT', 0, 116);
  ctx.font = '13px Courier New, monospace';
  ctx.letterSpacing = '8px';
  ctx.fillText('NO GODS / NO MERCY', 0, -118);
  return textureFromCanvas(canvas);
}

function skyMaterial() {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      top: { value: new THREE.Color(0x08090f) },
      horizon: { value: new THREE.Color(0x9b3b1c) },
      bottom: { value: new THREE.Color(0x1b0905) },
      sunDir: { value: new THREE.Vector3(-0.42, 0.31, -0.85).normalize() },
    },
    vertexShader: /* glsl */ `
      varying vec3 vWorld;
      void main() {
        vec4 world = modelMatrix * vec4(position, 1.0);
        vWorld = world.xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: /* glsl */ `
      varying vec3 vWorld;
      uniform vec3 top;
      uniform vec3 horizon;
      uniform vec3 bottom;
      uniform vec3 sunDir;
      void main() {
        vec3 dir = normalize(vWorld);
        float h = dir.y;
        vec3 col = mix(bottom, horizon, smoothstep(-0.18, 0.08, h));
        col = mix(col, top, smoothstep(0.08, 0.72, h));
        float sun = pow(max(dot(dir, sunDir), 0.0), 180.0);
        float glow = pow(max(dot(dir, sunDir), 0.0), 9.0);
        col += vec3(1.0, 0.42, 0.13) * sun * 1.6;
        col += vec3(0.65, 0.18, 0.05) * glow * 0.34;
        float band = smoothstep(0.24, 0.0, abs(h - 0.08)) * 0.14;
        col += vec3(0.38, 0.1, 0.04) * band;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
}

export class Arena {
  constructor(scene, renderer) {
    this.scene = scene;
    this.renderer = renderer;
    this.group = new THREE.Group();
    this.group.name = 'arena';
    scene.add(this.group);
    this.cheerTime = 0;
    this.time = 0;
    this.braziers = [];
    this.banners = [];
    this.spawnPoints = [
      new THREE.Vector3(1.5, 0, -14.4),
      new THREE.Vector3(-14.4, 0, -1.6),
      new THREE.Vector3(-1.2, 0, 14.5),
      new THREE.Vector3(14.5, 0, 1.2),
    ];
    this.radius = 17.6;
    this.build();
  }

  build() {
    const scene = this.scene;
    scene.fog = new THREE.FogExp2(0x29120a, 0.014);

    this.sky = new THREE.Mesh(new THREE.SphereGeometry(120, 32, 20), skyMaterial());
    this.group.add(this.sky);

    const hemi = new THREE.HemisphereLight(0x8a5d3b, 0x0d0805, 0.72);
    scene.add(hemi);

    const sun = new THREE.DirectionalLight(0xffb277, 3.4);
    sun.position.set(-22, 31, 15);
    sun.castShadow = true;
    sun.shadow.mapSize.set(1536, 1536);
    sun.shadow.camera.left = -28;
    sun.shadow.camera.right = 28;
    sun.shadow.camera.top = 28;
    sun.shadow.camera.bottom = -28;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 80;
    sun.shadow.bias = -0.0004;
    sun.shadow.normalBias = 0.045;
    scene.add(sun);
    this.sun = sun;

    const rim = new THREE.DirectionalLight(0xc84324, 1.15);
    rim.position.set(18, 8, -16);
    scene.add(rim);

    const fill = new THREE.PointLight(0xff6a32, 28, 34, 1.5);
    fill.position.set(0, 7, 0);
    scene.add(fill);

    // Sand floor.
    const floorMaterial = new THREE.MeshStandardMaterial({
      map: sandTexture(),
      color: 0xc29a63,
      roughness: 0.97,
      metalness: 0,
    });
    this.floor = new THREE.Mesh(new THREE.CircleGeometry(18.9, 96), floorMaterial);
    this.floor.rotation.x = -Math.PI / 2;
    this.floor.receiveShadow = true;
    this.group.add(this.floor);

    // Painted arena sigil.
    const emblem = new THREE.Mesh(
      new THREE.CircleGeometry(8.2, 64),
      new THREE.MeshBasicMaterial({
        map: emblemTexture(),
        transparent: true,
        opacity: 0.46,
        depthWrite: false,
      }),
    );
    emblem.rotation.x = -Math.PI / 2;
    emblem.position.y = 0.012;
    emblem.renderOrder = 1;
    this.group.add(emblem);

    // Low inner wall.
    const stoneMap = stoneTexture();
    const stoneMaterial = new THREE.MeshStandardMaterial({
      map: stoneMap,
      color: 0x8d7254,
      roughness: 0.92,
      metalness: 0.03,
    });
    this.wallMaterial = stoneMaterial;
    const wall = new THREE.Mesh(new THREE.CylinderGeometry(19.2, 19.5, 2.7, 72, 1, true), stoneMaterial);
    wall.position.y = 1.35;
    wall.material.side = THREE.DoubleSide;
    wall.receiveShadow = true;
    this.group.add(wall);

    const wallInner = new THREE.Mesh(
      new THREE.CylinderGeometry(19.1, 19.2, 2.55, 72, 1, true),
      new THREE.MeshStandardMaterial({ color: 0x2a1d14, roughness: 1, side: THREE.BackSide }),
    );
    wallInner.position.y = 1.35;
    this.group.add(wallInner);

    // Stone lip and tiered stands.
    const lip = new THREE.Mesh(new THREE.TorusGeometry(19.15, 0.13, 5, 72), stoneMaterial);
    lip.rotation.x = Math.PI / 2;
    lip.position.y = 2.7;
    lip.castShadow = true;
    this.group.add(lip);

    for (let row = 0; row < 6; row++) {
      const inner = 19.1 + row * 1.25;
      const outer = inner + 1.27;
      const step = new THREE.Mesh(
        new THREE.RingGeometry(inner, outer, 72),
        new THREE.MeshStandardMaterial({
          color: row % 2 ? 0x4f3926 : 0x39291d,
          roughness: 0.95,
          side: THREE.DoubleSide,
        }),
      );
      step.rotation.x = -Math.PI / 2;
      step.position.y = 2.64 + row * 0.47;
      step.receiveShadow = true;
      this.group.add(step);
    }

    // Tall rear wall to give the horizon weight.
    const backWall = new THREE.Mesh(
      new THREE.CylinderGeometry(27.2, 27.2, 5.8, 72, 1, true),
      new THREE.MeshStandardMaterial({ map: stoneMap, color: 0x4b3726, roughness: 0.96, side: THREE.BackSide }),
    );
    backWall.position.y = 5.3;
    this.group.add(backWall);

    this.buildCrowd();
    this.buildGates();
    this.buildBanners();
    this.buildBraziers();
    this.buildProps();
    this.buildDust();
  }

  buildCrowd() {
    const count = 230;
    const bodyGeo = new THREE.BoxGeometry(0.3, 0.5, 0.25);
    const headGeo = new THREE.IcosahedronGeometry(0.125, 1);
    const bodyMat = new THREE.MeshStandardMaterial({ roughness: 0.94, vertexColors: false });
    const headMat = new THREE.MeshStandardMaterial({ roughness: 0.9 });
    const bodies = new THREE.InstancedMesh(bodyGeo, bodyMat, count);
    const heads = new THREE.InstancedMesh(headGeo, headMat, count);
    bodies.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    heads.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    bodies.castShadow = false;
    bodies.receiveShadow = false;

    const cloth = [0x5a2c21, 0x3b2920, 0x6f3d26, 0x2d322d, 0x563a23, 0x44211c, 0x5c4b31, 0x3d2028];
    const skins = [0xb98c64, 0x9e6f4e, 0x7b5139, 0xc49a71, 0x8b5f43, 0x6e4632];
    const figures = [];
    const matrix = new THREE.Matrix4();
    const quat = new THREE.Quaternion();
    const euler = new THREE.Euler();
    const scale = new THREE.Vector3();
    const position = new THREE.Vector3();

    for (let i = 0; i < count; i++) {
      const row = i % 6;
      const angle = (Math.floor(i / 6) / Math.ceil(count / 6)) * TAU + rand(-0.035, 0.035);
      const radius = 21.0 + row * 1.24 + rand(-0.16, 0.16);
      const y = 3.1 + row * 0.47;
      const facing = Math.atan2(-Math.cos(angle), -Math.sin(angle));
      const phase = rand(0, TAU);
      const lean = rand(-0.06, 0.08);
      figures.push({ angle, radius, y, facing, phase, row, lean, scale: rand(0.88, 1.10) });

      position.set(Math.cos(angle) * radius, y + 0.27, Math.sin(angle) * radius);
      euler.set(0, facing, lean);
      quat.setFromEuler(euler);
      scale.setScalar(figures[i].scale);
      matrix.compose(position, quat, scale);
      bodies.setMatrixAt(i, matrix);
      bodies.setColorAt(i, new THREE.Color(pick(cloth)).multiplyScalar(rand(0.66, 1.1)));

      position.y = y + 0.62;
      scale.setScalar(figures[i].scale);
      matrix.compose(position, quat, scale);
      heads.setMatrixAt(i, matrix);
      heads.setColorAt(i, new THREE.Color(pick(skins)).multiplyScalar(rand(0.7, 1.1)));
    }

    bodies.instanceColor.needsUpdate = true;
    heads.instanceColor.needsUpdate = true;
    this.group.add(bodies, heads);
    this.crowd = { bodies, heads, figures, count };
    this._crowdMatrix = matrix;
    this._crowdQuat = quat;
    this._crowdEuler = euler;
    this._crowdScale = scale;
    this._crowdPos = position;
  }

  buildGates() {
    const gateMat = new THREE.MeshStandardMaterial({ color: 0x1b110b, roughness: 0.9 });
    const ironMat = new THREE.MeshStandardMaterial({ color: 0x2e2620, metalness: 0.72, roughness: 0.55 });
    const trimMat = new THREE.MeshStandardMaterial({ color: 0x6d5536, roughness: 0.8, metalness: 0.08 });
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * TAU + Math.PI / 4;
      const gate = new THREE.Group();
      gate.position.set(Math.cos(angle) * 19.1, 0, Math.sin(angle) * 19.1);
      gate.rotation.y = -angle + Math.PI / 2;
      this.group.add(gate);

      const archMesh = new THREE.Mesh(new THREE.BoxGeometry(3.5, 3.8, 0.28), gateMat);
      archMesh.position.y = 1.9;
      gate.add(archMesh);

      for (const side of [-1, 1]) {
        const pillar = new THREE.Mesh(new THREE.BoxGeometry(0.38, 4.4, 0.7), trimMat);
        pillar.position.set(side * 1.73, 2.2, 0.12);
        pillar.castShadow = true;
        gate.add(pillar);
        const skull = new THREE.Mesh(new THREE.IcosahedronGeometry(0.14, 1), new THREE.MeshStandardMaterial({ color: 0xd0bd94, roughness: 0.8 }));
        skull.position.set(side * 1.73, 4.05, 0.5);
        gate.add(skull);
      }

      const lintel = new THREE.Mesh(new THREE.BoxGeometry(3.9, 0.5, 0.75), trimMat);
      lintel.position.y = 4.23;
      lintel.castShadow = true;
      gate.add(lintel);

      // Portcullis behind the dark gate mouth.
      const barGeo = new THREE.CylinderGeometry(0.026, 0.026, 3.1, 6);
      for (let b = 0; b < 8; b++) {
        const bar = new THREE.Mesh(barGeo, ironMat);
        bar.position.set(-1.15 + b * 0.33, 1.9, -0.17);
        gate.add(bar);
      }
      const cross = new THREE.Mesh(new THREE.BoxGeometry(2.62, 0.05, 0.05), ironMat);
      cross.position.set(0, 1.25, -0.14);
      gate.add(cross);
      const cross2 = cross.clone();
      cross2.position.y = 2.62;
      gate.add(cross2);
    }
  }

  buildBanners() {
    const map = bannerTexture();
    const material = new THREE.MeshStandardMaterial({
      map,
      color: 0xcdb087,
      roughness: 0.98,
      side: THREE.DoubleSide,
      transparent: true,
      alphaTest: 0.08,
    });
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * TAU + 0.32;
      const group = new THREE.Group();
      group.position.set(Math.cos(angle) * 18.7, 0, Math.sin(angle) * 18.7);
      group.rotation.y = -angle + Math.PI;

      const pole = new THREE.Mesh(
        new THREE.CylinderGeometry(0.035, 0.035, 4.8, 6),
        new THREE.MeshStandardMaterial({ color: 0x241710, roughness: 0.7 }),
      );
      pole.position.y = 2.45;
      group.add(pole);

      const banner = new THREE.Mesh(new THREE.PlaneGeometry(1.65, 3.3), material);
      banner.position.set(0.86, 2.72, 0);
      banner.rotation.z = -0.025;
      group.add(banner);
      this.banners.push({ mesh: banner, base: -0.025, phase: rand(0, TAU) });
      this.group.add(group);
    }
  }

  buildBraziers() {
    const stone = new THREE.MeshStandardMaterial({ color: 0x3c2b1d, roughness: 0.96 });
    const iron = new THREE.MeshStandardMaterial({ color: 0x241b14, metalness: 0.65, roughness: 0.5 });
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * TAU;
      const x = Math.cos(angle) * 13.4;
      const z = Math.sin(angle) * 13.4;
      const base = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.48, 1.5, 7), stone);
      base.position.set(x, 0.75, z);
      base.castShadow = true;
      this.group.add(base);

      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.72, 0.33, 0.35, 9, 1, true), iron);
      bowl.position.set(x, 1.63, z);
      this.group.add(bowl);

      const coal = new THREE.Mesh(
        new THREE.CylinderGeometry(0.6, 0.6, 0.06, 9),
        new THREE.MeshBasicMaterial({ color: 0xff5b1e }),
      );
      coal.position.set(x, 1.67, z);
      this.group.add(coal);

      const light = new THREE.PointLight(0xff5a24, 22, 13, 1.8);
      light.position.set(x, 2.2, z);
      this.group.add(light);

      const count = 26;
      const positions = new Float32Array(count * 3);
      const colors = new Float32Array(count * 3);
      const particles = [];
      for (let p = 0; p < count; p++) {
        particles.push(this.resetFlameParticle([], false));
        positions[p * 3] = x;
        positions[p * 3 + 1] = 1.9;
        positions[p * 3 + 2] = z;
        colors[p * 3] = 1;
        colors[p * 3 + 1] = 0.34;
        colors[p * 3 + 2] = 0.08;
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
      geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
      const mat = new THREE.PointsMaterial({
        size: 0.22,
        map: radialTexture(32, 'rgba(255,235,190,1)', 'rgba(255,90,20,0)'),
        transparent: true,
        opacity: 0.9,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        vertexColors: true,
        sizeAttenuation: true,
      });
      const points = new THREE.Points(geo, mat);
      points.position.set(0, 0, 0);
      this.group.add(points);
      this.braziers.push({ x, z, points, particles, light, baseIntensity: 22 });
    }
  }

  resetFlameParticle(target, randomize = true) {
    target[0] = rand(-0.34, 0.34);
    target[1] = randomize ? rand(0, 1.5) : rand(0, 0.4);
    target[2] = rand(-0.34, 0.34);
    target[3] = rand(0.7, 1.8);
    target[4] = rand(0.35, 0.75);
    return target;
  }

  buildProps() {
    const boneMat = new THREE.MeshStandardMaterial({ color: 0xbcaa86, roughness: 0.78 });
    const ironMat = new THREE.MeshStandardMaterial({ color: 0x35302a, metalness: 0.55, roughness: 0.55 });
    const woodMat = new THREE.MeshStandardMaterial({ color: 0x4b321f, roughness: 0.9 });
    const props = new THREE.Group();

    // Broken spears near the wall.
    for (let i = 0; i < 9; i++) {
      const angle = rand(0, TAU);
      const radius = rand(15.2, 18.1);
      const group = new THREE.Group();
      group.position.set(Math.cos(angle) * radius, 0.06, Math.sin(angle) * radius);
      group.rotation.set(rand(-0.1, 0.1), rand(0, TAU), Math.PI / 2 + rand(-0.15, 0.15));
      const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.035, rand(1.8, 3.1), 5), woodMat);
      const tip = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.3, 4), ironMat);
      tip.position.y = 1.55;
      group.add(shaft, tip);
      props.add(group);
    }

    // Skulls and ribs half-buried in the sand.
    for (let i = 0; i < 16; i++) {
      const angle = rand(0, TAU);
      const radius = rand(5.6, 17.4);
      const skull = new THREE.Group();
      skull.position.set(Math.cos(angle) * radius, 0.08, Math.sin(angle) * radius);
      skull.rotation.set(rand(-0.2, 0.2), rand(0, TAU), rand(-0.3, 0.3));
      const cranium = new THREE.Mesh(new THREE.IcosahedronGeometry(rand(0.1, 0.15), 1), boneMat);
      cranium.scale.set(1, 0.86, 1.12);
      skull.add(cranium);
      const jaw = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.045, 0.11), boneMat);
      jaw.position.set(0, -0.11, 0.04);
      skull.add(jaw);
      props.add(skull);
    }

    // Discarded helms and a fallen shield.
    for (let i = 0; i < 4; i++) {
      const angle = rand(0, TAU);
      const radius = rand(12.5, 17.8);
      const helm = new THREE.Mesh(new THREE.SphereGeometry(0.26, 8, 5, 0, TAU, 0, Math.PI / 2), ironMat);
      helm.position.set(Math.cos(angle) * radius, 0.05, Math.sin(angle) * radius);
      helm.rotation.set(Math.PI, rand(0, TAU), rand(-0.2, 0.2));
      props.add(helm);
    }
    const shield = new THREE.Mesh(new THREE.CylinderGeometry(0.58, 0.58, 0.06, 12), ironMat);
    shield.position.set(-7.5, 0.05, 9.5);
    shield.rotation.set(Math.PI / 2, 0, 0.6);
    props.add(shield);

    this.group.add(props);
  }

  buildDust() {
    const count = 150;
    const positions = new Float32Array(count * 3);
    const seeds = [];
    for (let i = 0; i < count; i++) {
      const angle = rand(0, TAU);
      const radius = Math.sqrt(Math.random()) * 18;
      positions[i * 3] = Math.cos(angle) * radius;
      positions[i * 3 + 1] = rand(0.3, 6.5);
      positions[i * 3 + 2] = Math.sin(angle) * radius;
      seeds.push({ speed: rand(0.04, 0.16), phase: rand(0, TAU), drift: rand(0.2, 0.8) });
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      size: 0.035,
      color: 0xffc58a,
      transparent: true,
      opacity: 0.36,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      map: radialTexture(16, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)'),
    });
    this.dust = new THREE.Points(geo, mat);
    this.dustSeeds = seeds;
    this.group.add(this.dust);
  }

  triggerCheer() {
    this.cheerTime = 3.8;
    for (const brazier of this.braziers) {
      brazier.light.intensity = brazier.baseIntensity * 1.65;
    }
  }

  update(dt, time, menuMode = false) {
    this.time = time;
    const cheer = Math.max(0, this.cheerTime);
    this.cheerTime = Math.max(0, this.cheerTime - dt);
    const cheerStrength = clamp(cheer / 3.8, 0, 1);
    const cheerActive = cheer > 0;

    // Crowd idle and celebration bounce.
    const { bodies, heads, figures, count } = this.crowd;
    const m = this._crowdMatrix;
    const q = this._crowdQuat;
    const e = this._crowdEuler;
    const s = this._crowdScale;
    const p = this._crowdPos;

    if (cheerActive || menuMode || time % 0.1 < dt) {
      for (let i = 0; i < count; i++) {
        const figure = figures[i];
        const bounce = cheerActive
          ? Math.abs(Math.sin(time * 8.2 + figure.phase)) * 0.2 * cheerStrength
          : Math.sin(time * 0.8 + figure.phase) * 0.012;
        const sway = cheerActive ? Math.sin(time * 5.2 + figure.phase) * 0.12 * cheerStrength : 0;
        p.set(Math.cos(figure.angle) * figure.radius, figure.y + 0.27 + bounce, Math.sin(figure.angle) * figure.radius);
        e.set(0, figure.facing + sway, figure.lean + sway * 0.4);
        q.setFromEuler(e);
        s.setScalar(figure.scale * (cheerActive ? 1 + bounce * 0.22 : 1));
        m.compose(p, q, s);
        bodies.setMatrixAt(i, m);
        p.y = figure.y + 0.62 + bounce * 1.1;
        m.compose(p, q, s);
        heads.setMatrixAt(i, m);
      }
      bodies.instanceMatrix.needsUpdate = true;
      heads.instanceMatrix.needsUpdate = true;
    }

    // Braziers.
    for (const brazier of this.braziers) {
      const positions = brazier.points.geometry.attributes.position.array;
      brazier.particles.forEach((particle, index) => {
        particle[1] += dt * particle[3];
        particle[0] += dt * Math.sin(time * 2 + index) * 0.09;
        particle[2] += dt * Math.cos(time * 1.6 + index * 0.8) * 0.09;
        if (particle[1] > 1.42) {
          this.resetFlameParticle(particle, false);
        }
        positions[index * 3] = brazier.x + particle[0];
        positions[index * 3 + 1] = 1.86 + particle[1];
        positions[index * 3 + 2] = brazier.z + particle[2];
      });
      brazier.points.geometry.attributes.position.needsUpdate = true;
      brazier.points.material.opacity = 0.72 + Math.sin(time * 9 + brazier.x) * 0.16;
      brazier.light.intensity = brazier.baseIntensity * (0.82 + Math.sin(time * 12 + brazier.z) * 0.18 + (cheerActive ? 0.55 * cheerStrength : 0));
    }

    // Dust drift.
    if (this.dust) {
      const positions = this.dust.geometry.attributes.position.array;
      for (let i = 0; i < this.dustSeeds.length; i++) {
        const seed = this.dustSeeds[i];
        positions[i * 3] += Math.sin(time * 0.3 + seed.phase) * dt * 0.12;
        positions[i * 3 + 1] += dt * seed.speed * 0.12;
        positions[i * 3 + 2] += Math.cos(time * 0.25 + seed.phase) * dt * 0.1;
        if (positions[i * 3 + 1] > 7) positions[i * 3 + 1] = 0.3;
      }
      this.dust.geometry.attributes.position.needsUpdate = true;
    }

    // Banners shiver.
    for (const banner of this.banners) {
      banner.mesh.rotation.z = banner.base + Math.sin(time * 0.8 + banner.phase) * 0.019;
      banner.mesh.rotation.y = Math.sin(time * 0.5 + banner.phase) * 0.035;
    }
  }

  reset() {
    this.cheerTime = 0;
  }
}

import * as THREE from 'three';
import {
  canvas2d,
  textureFromCanvas,
  radialTexture,
  rand,
  randInt,
  pick,
  clamp,
  TAU,
} from './utils.js';

function makeSplatTexture(seed = 1) {
  const { canvas, ctx } = canvas2d(128);
  ctx.clearRect(0, 0, 128, 128);
  const r = (min, max) => min + Math.random() * (max - min);

  // Central impact blot.
  const cx = 64 + r(-7, 7);
  const cy = 64 + r(-7, 7);
  const gradient = ctx.createRadialGradient(cx, cy, 2, cx, cy, 44);
  gradient.addColorStop(0, 'rgba(104, 0, 2, .98)');
  gradient.addColorStop(0.55, 'rgba(78, 0, 2, .82)');
  gradient.addColorStop(1, 'rgba(48, 0, 2, 0)');
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(cx, cy, 44, 0, TAU);
  ctx.fill();

  // Irregular lobes.
  for (let i = 0; i < 16; i++) {
    const angle = r(0, TAU);
    const dist = r(10, 38);
    const radius = r(5, 19);
    ctx.fillStyle = `rgba(${r(48, 104) | 0}, 0, ${r(0, 5) | 0}, ${r(0.4, 0.88)})`;
    ctx.beginPath();
    ctx.ellipse(cx + Math.cos(angle) * dist, cy + Math.sin(angle) * dist, radius, radius * r(0.35, 1), angle, 0, TAU);
    ctx.fill();
  }

  // Satellite droplets.
  for (let i = 0; i < 34; i++) {
    const angle = r(0, TAU);
    const dist = r(30, 62);
    const radius = r(0.8, 5.2);
    ctx.fillStyle = `rgba(${r(52, 122) | 0}, 0, ${r(0, 4) | 0}, ${r(0.32, 0.9)})`;
    ctx.beginPath();
    ctx.ellipse(cx + Math.cos(angle) * dist, cy + Math.sin(angle) * dist, radius, radius * r(0.3, 2.2), angle, 0, TAU);
    ctx.fill();
  }

  // Directional spray lines.
  for (let i = 0; i < 5; i++) {
    const angle = r(0, TAU);
    ctx.strokeStyle = `rgba(80, 0, 2, ${r(0.2, 0.5)})`;
    ctx.lineWidth = r(1, 3);
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + Math.cos(angle) * r(36, 57), cy + Math.sin(angle) * r(36, 57));
    ctx.stroke();
  }
  return textureFromCanvas(canvas);
}

function makeWallSplatTexture() {
  const { canvas, ctx } = canvas2d(128, 256);
  ctx.clearRect(0, 0, 128, 256);
  const gradient = ctx.createRadialGradient(64, 44, 2, 64, 44, 46);
  gradient.addColorStop(0, 'rgba(112, 0, 2, .96)');
  gradient.addColorStop(0.5, 'rgba(74, 0, 2, .8)');
  gradient.addColorStop(1, 'rgba(45, 0, 1, 0)');
  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.ellipse(64, 44, 48, 40, 0, 0, TAU);
  ctx.fill();

  for (let i = 0; i < 14; i++) {
    ctx.fillStyle = `rgba(${randInt(45, 100)}, 0, 1, ${rand(0.35, 0.85)})`;
    ctx.beginPath();
    ctx.ellipse(rand(20, 108), rand(25, 100), rand(5, 18), rand(3, 13), rand(0, TAU), 0, TAU);
    ctx.fill();
  }
  // Drips.
  for (let i = 0; i < 19; i++) {
    const x = rand(22, 106);
    const y = rand(48, 116);
    const length = rand(12, 118);
    const width = rand(1.1, 4.2);
    const dripGrad = ctx.createLinearGradient(0, y, 0, y + length);
    dripGrad.addColorStop(0, `rgba(${randInt(55, 105)}, 0, 2, ${rand(0.4, 0.86)})`);
    dripGrad.addColorStop(1, 'rgba(42, 0, 1, 0)');
    ctx.fillStyle = dripGrad;
    ctx.fillRect(x, y, width, length);
    if (Math.random() > 0.4) {
      ctx.beginPath();
      ctx.arc(x + width / 2, y + length, width * 1.5, 0, TAU);
      ctx.fillStyle = 'rgba(64, 0, 2, .5)';
      ctx.fill();
    }
  }
  return textureFromCanvas(canvas);
}

export class Effects {
  constructor(scene, arena) {
    this.scene = scene;
    this.arena = arena;
    this.particleCount = 640;
    this.particles = [];
    this.decals = [];
    this.debris = [];
    this.transients = [];

    this.splatMaps = [makeSplatTexture(), makeSplatTexture(), makeSplatTexture()];
    this.wallMaps = [makeWallSplatTexture(), makeWallSplatTexture()];
    this.decalGeometry = new THREE.PlaneGeometry(1, 1);
    this.wallDecalGeometry = new THREE.PlaneGeometry(1, 1);
    this.decalCount = 0;

    this.initParticles();
  }

  initParticles() {
    const positions = new Float32Array(this.particleCount * 3);
    const colors = new Float32Array(this.particleCount * 3);
    positions.fill(-1000);
    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    const material = new THREE.PointsMaterial({
      size: 0.075,
      map: radialTexture(32, 'rgba(255,255,255,1)', 'rgba(255,255,255,0)'),
      transparent: true,
      opacity: 0.95,
      depthWrite: false,
      vertexColors: true,
      blending: THREE.NormalBlending,
      sizeAttenuation: true,
    });
    const points = new THREE.Points(geometry, material);
    points.frustumCulled = false;
    points.renderOrder = 3;
    this.scene.add(points);
    this.points = points;
    this.particleCursor = 0;
    for (let i = 0; i < this.particleCount; i++) {
      this.particles.push({
        active: false,
        pos: new THREE.Vector3(),
        vel: new THREE.Vector3(),
        gravity: 9.8,
        life: 0,
        maxLife: 1,
        drag: 0.99,
      });
      positions[i * 3 + 1] = -1000;
    }
    geometry.attributes.position.needsUpdate = true;
  }

  emit(position, direction, count, options = {}) {
    const {
      speed = 3.3,
      spread = 0.85,
      gravity = 9.8,
      life = 0.65,
      colors = [
        [0.38, 0.005, 0.008],
        [0.56, 0.008, 0.01],
        [0.71, 0.02, 0.015],
        [0.29, 0.002, 0.004],
      ],
      drag = 0.992,
      bias = 0.35,
    } = options;
    const positions = this.points.geometry.attributes.position.array;
    const colorArray = this.points.geometry.attributes.color.array;
    for (let i = 0; i < count; i++) {
      const index = this.particleCursor;
      this.particleCursor = (this.particleCursor + 1) % this.particleCount;
      const particle = this.particles[index];
      particle.active = true;
      particle.pos.copy(position);
      particle.pos.x += rand(-0.12, 0.12);
      particle.pos.y += rand(-0.08, 0.2);
      particle.pos.z += rand(-0.12, 0.12);
      const vx = direction.x + rand(-spread, spread);
      const vy = direction.y + rand(-spread * 0.55, spread) + bias;
      const vz = direction.z + rand(-spread, spread);
      const scale = speed * rand(0.25, 1.2);
      particle.vel.set(vx, vy, vz).normalize().multiplyScalar(scale);
      particle.gravity = gravity;
      particle.life = life * rand(0.5, 1.35);
      particle.maxLife = particle.life;
      particle.drag = drag;
      const c = pick(colors);
      colorArray[index * 3] = c[0];
      colorArray[index * 3 + 1] = c[1];
      colorArray[index * 3 + 2] = c[2];
      positions[index * 3] = particle.pos.x;
      positions[index * 3 + 1] = particle.pos.y;
      positions[index * 3 + 2] = particle.pos.z;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;
  }

  bloodBurst(position, direction = new THREE.Vector3(0, 0.4, 1), intensity = 1) {
    this.emit(position, direction, Math.round(15 * intensity), {
      speed: 3.5 * intensity,
      spread: 0.95,
      life: 0.75,
    });
    this.emit(position, direction, Math.round(8 * intensity), {
      speed: 5.8 * intensity,
      spread: 0.55,
      life: 0.45,
      bias: 0.55,
      gravity: 11,
    });
    // Thick arterial spray is represented by long directional streaks.
    this.emit(position, direction, Math.round(5 * intensity), {
      speed: 6.4,
      spread: 0.12,
      life: 0.75,
      gravity: 9.8,
      bias: 0.25,
      drag: 0.985,
    });
    this.addBloodDecal(position, direction, intensity);
    if (Math.random() > 0.58) this.addBloodDecal(position, direction, intensity * 0.7, true);
  }

  bloodFountain(position, direction = new THREE.Vector3(0, 1, 0), intensity = 1) {
    this.emit(position, new THREE.Vector3(direction.x * 0.3, 1.1, direction.z * 0.3), Math.round(10 * intensity), {
      speed: 2.1,
      spread: 0.32,
      life: 0.9,
      gravity: 8,
      bias: 0.6,
    });
  }

  sparks(position, direction, count = 12) {
    this.emit(position, direction, count, {
      speed: 4.2,
      spread: 0.8,
      gravity: 7.5,
      life: 0.28,
      drag: 0.98,
      colors: [[1, 0.76, 0.29], [1, 0.93, 0.67], [1, 0.5, 0.12], [0.8, 0.24, 0.02]],
    });
  }

  addBloodDecal(position, direction = new THREE.Vector3(0, 0, 1), intensity = 1, forceWall = false) {
    const radial = Math.hypot(position.x, position.z);
    const isWall = forceWall || radial > 18.25 || (position.y > 1.2 && radial > 17.2);
    let mesh;
    if (isWall) {
      const angle = Math.atan2(position.z, position.x);
      const radius = 19.05;
      const y = clamp(position.y + rand(-0.15, 0.55), 0.3, 2.55);
      const material = new THREE.MeshBasicMaterial({
        map: pick(this.wallMaps),
        transparent: true,
        opacity: rand(0.45, 0.87) * clamp(intensity, 0.4, 1.35),
        depthWrite: false,
        side: THREE.DoubleSide,
        blending: THREE.NormalBlending,
      });
      mesh = new THREE.Mesh(this.wallDecalGeometry, material);
      const scale = rand(0.45, 1.15) * clamp(intensity, 0.5, 1.2);
      mesh.scale.set(scale * rand(0.7, 1.15), scale * rand(0.9, 1.35), 1);
      mesh.position.set(Math.cos(angle) * radius, y, Math.sin(angle) * radius);
      mesh.lookAt(0, y, 0);
      mesh.rotation.z = rand(-0.18, 0.18);
      mesh.renderOrder = 4;
    } else {
      const material = new THREE.MeshBasicMaterial({
        map: pick(this.splatMaps),
        transparent: true,
        opacity: rand(0.5, 0.86) * clamp(intensity, 0.4, 1.3),
        depthWrite: false,
        blending: THREE.NormalBlending,
        side: THREE.DoubleSide,
      });
      mesh = new THREE.Mesh(this.decalGeometry, material);
      const scale = rand(0.5, 1.35) * clamp(intensity, 0.45, 1.35);
      mesh.scale.set(scale * rand(0.8, 1.6), scale * rand(0.55, 1.4), 1);
      mesh.rotation.x = -Math.PI / 2;
      mesh.rotation.z = rand(0, TAU);
      mesh.position.set(
        position.x + direction.x * rand(0.2, 0.6) + rand(-0.25, 0.25),
        0.018 + this.decals.length * 0.00004,
        position.z + direction.z * rand(0.2, 0.6) + rand(-0.25, 0.25),
      );
      mesh.renderOrder = 2;
    }
    this.scene.add(mesh);
    this.decals.push(mesh);
    if (this.decals.length > 155) {
      const old = this.decals.shift();
      this.scene.remove(old);
      old.material.dispose();
    }
  }

  addDebris(object, velocity = new THREE.Vector3(), spin = new THREE.Vector3(), floor = 0.07) {
    object.userData.physics = {
      vel: velocity.clone(),
      spin: spin.clone(),
      floor,
      settled: false,
    };
    this.debris.push(object);
    return object;
  }

  updateDebris(dt) {
    for (const object of this.debris) {
      const physics = object.userData.physics;
      if (!physics || physics.settled) continue;
      physics.vel.y -= 12.5 * dt;
      object.position.addScaledVector(physics.vel, dt);
      object.rotation.x += physics.spin.x * dt;
      object.rotation.y += physics.spin.y * dt;
      object.rotation.z += physics.spin.z * dt;
      if (object.position.y < physics.floor) {
        object.position.y = physics.floor;
        if (Math.abs(physics.vel.y) > 1.2) {
          physics.vel.y *= -0.27;
          physics.vel.x *= 0.58;
          physics.vel.z *= 0.58;
          physics.spin.multiplyScalar(0.62);
          if (Math.random() > 0.6) {
            this.emit(object.position, new THREE.Vector3(0, 0.6, 0), 2, {
              speed: 1.2,
              spread: 0.9,
              life: 0.35,
              gravity: 6,
              colors: [[0.32, 0.002, 0.003], [0.5, 0.006, 0.005]],
            });
          }
        } else {
          physics.vel.set(0, 0, 0);
          physics.spin.set(0, 0, 0);
          physics.settled = true;
        }
      }
      const radial = Math.hypot(object.position.x, object.position.z);
      if (radial > 18.4) {
        object.position.x *= 18.4 / radial;
        object.position.z *= 18.4 / radial;
        physics.vel.x *= -0.3;
        physics.vel.z *= -0.3;
      }
    }
  }

  createGuts(position, direction) {
    const group = new THREE.Group();
    group.position.copy(position);
    const intestineMat = new THREE.MeshStandardMaterial({
      color: 0x6e2626,
      roughness: 0.72,
      metalness: 0.02,
      flatShading: true,
    });
    const fatMat = new THREE.MeshStandardMaterial({ color: 0xb68168, roughness: 0.82 });
    for (let i = 0; i < 4; i++) {
      const points = [];
      const length = randInt(3, 5);
      for (let j = 0; j < length; j++) {
        points.push(new THREE.Vector3(rand(-0.3, 0.3), rand(-0.1, 0.3), rand(-0.35, 0.35)));
      }
      const curve = new THREE.CatmullRomCurve3(points);
      const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 12, rand(0.035, 0.075), 5, false), intestineMat);
      group.add(tube);
    }
    for (let i = 0; i < 7; i++) {
      const blob = new THREE.Mesh(new THREE.IcosahedronGeometry(rand(0.04, 0.1), 1), Math.random() > 0.3 ? intestineMat : fatMat);
      blob.position.set(rand(-0.32, 0.32), rand(-0.1, 0.3), rand(-0.32, 0.32));
      group.add(blob);
    }
    this.scene.add(group);
    const velocity = new THREE.Vector3(direction.x * rand(1.2, 2.8) + rand(-0.8, 0.8), rand(1.5, 3.6), direction.z * rand(1.2, 2.8) + rand(-0.8, 0.8));
    this.addDebris(group, velocity, new THREE.Vector3(rand(-6, 6), rand(-6, 6), rand(-6, 6)), 0.04);
    this.bloodBurst(position, direction, 1.8);
    return group;
  }

  createBone(position, direction, length = 0.35, radius = 0.04) {
    const material = new THREE.MeshStandardMaterial({ color: 0xe5d6b8, roughness: 0.7, flatShading: true });
    const bone = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius * 0.8, length, 5), material);
    bone.position.copy(position);
    bone.rotation.set(rand(-1, 1), rand(0, TAU), rand(-1, 1));
    this.scene.add(bone);
    this.addDebris(
      bone,
      new THREE.Vector3(direction.x * rand(0.8, 2.4), rand(1.5, 3.3), direction.z * rand(0.8, 2.4)),
      new THREE.Vector3(rand(-8, 8), rand(-8, 8), rand(-8, 8)),
      0.05,
    );
    return bone;
  }

  createBrain(position, direction) {
    const brain = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({ color: 0xc27b79, roughness: 0.55 });
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(0.13, 2), mat);
    core.scale.set(1, 0.72, 1.12);
    brain.add(core);
    for (let i = 0; i < 7; i++) {
      const lobe = new THREE.Mesh(new THREE.IcosahedronGeometry(rand(0.035, 0.075), 1), mat);
      lobe.position.set(rand(-0.13, 0.13), rand(-0.06, 0.08), rand(-0.13, 0.13));
      brain.add(lobe);
    }
    brain.position.copy(position);
    this.scene.add(brain);
    this.addDebris(
      brain,
      new THREE.Vector3(direction.x * rand(0.5, 1.8), rand(1.4, 3), direction.z * rand(0.5, 1.8)),
      new THREE.Vector3(rand(-6, 6), rand(-6, 6), rand(-6, 6)),
      0.12,
    );
    return brain;
  }

  createSkullFragment(position, direction, side = 1) {
    const mat = new THREE.MeshStandardMaterial({ color: 0xcfb995, roughness: 0.62, flatShading: true });
    const geo = new THREE.SphereGeometry(0.18, 9, 6, 0, Math.PI, 0, Math.PI * 0.72);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(position);
    mesh.rotation.set(rand(-0.4, 0.4), side * rand(1.2, 2.2), rand(-0.5, 0.5));
    mesh.scale.set(1, 0.95, 1.1);
    this.scene.add(mesh);
    this.addDebris(
      mesh,
      new THREE.Vector3(direction.x * rand(0.5, 2) + side * rand(0.8, 2), rand(1.2, 3.2), direction.z * rand(0.5, 2)),
      new THREE.Vector3(rand(-9, 9), rand(-9, 9), rand(-9, 9)),
      0.12,
    );
    return mesh;
  }

  hammerShockwave(position, radius = 3.2) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.35, 0.55, 40),
      new THREE.MeshBasicMaterial({
        color: 0xf3b064,
        transparent: true,
        opacity: 0.65,
        side: THREE.DoubleSide,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
      }),
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.copy(position);
    ring.position.y = 0.06;
    this.scene.add(ring);
    this.transients.push({ mesh: ring, age: 0, maxAge: 0.5, type: 'ring', radius });
    this.emit(position, new THREE.Vector3(0, 1, 0), 16, {
      speed: 2.8,
      spread: 0.65,
      gravity: 3.5,
      life: 0.4,
      colors: [[0.95, 0.7, 0.4], [0.7, 0.5, 0.32], [0.36, 0.23, 0.13]],
    });
  }

  update(dt) {
    const positions = this.points.geometry.attributes.position.array;
    for (let i = 0; i < this.particleCount; i++) {
      const p = this.particles[i];
      if (!p.active) continue;
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        positions[i * 3 + 1] = -1000;
        continue;
      }
      p.vel.y -= p.gravity * dt;
      p.vel.multiplyScalar(Math.pow(p.drag, dt * 60));
      p.pos.addScaledVector(p.vel, dt);
      positions[i * 3] = p.pos.x;
      positions[i * 3 + 1] = p.pos.y;
      positions[i * 3 + 2] = p.pos.z;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.updateDebris(dt);

    for (let i = this.transients.length - 1; i >= 0; i--) {
      const t = this.transients[i];
      t.age += dt;
      const progress = t.age / t.maxAge;
      if (t.type === 'ring') {
        const scale = 1 + progress * t.radius * 2.4;
        t.mesh.scale.set(scale, scale, 1);
        t.mesh.material.opacity = 0.65 * (1 - progress);
      }
      if (progress >= 1) {
        this.scene.remove(t.mesh);
        t.mesh.geometry.dispose();
        t.mesh.material.dispose();
        this.transients.splice(i, 1);
      }
    }
  }

  clearWave() {
    for (const decal of this.decals) {
      this.scene.remove(decal);
      decal.material.dispose();
    }
    this.decals.length = 0;

    for (const object of this.debris) {
      this.scene.remove(object);
      object.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose?.();
          const materials = Array.isArray(child.material) ? child.material : [child.material];
          for (const material of materials) material?.dispose?.();
        }
      });
    }
    this.debris.length = 0;

    for (const t of this.transients) {
      this.scene.remove(t.mesh);
      t.mesh.geometry.dispose();
      t.mesh.material.dispose();
    }
    this.transients.length = 0;

    const positions = this.points.geometry.attributes.position.array;
    for (let i = 0; i < this.particleCount; i++) {
      this.particles[i].active = false;
      positions[i * 3 + 1] = -1000;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
  }
}

